package com.hrcoresystem.hrcore_api.modules.tenant.positions.application.usecase;
import com.hrcoresystem.hrcore_api.modules.platform.tenantsettings.application.service.TenantTimezoneService; import com.hrcoresystem.hrcore_api.modules.tenant.departments.application.dto.OrganizationalEmployeeSummaryResponse; import com.hrcoresystem.hrcore_api.modules.tenant.positions.domain.repository.PositionRepository; import com.hrcoresystem.hrcore_api.modules.tenant.employees.domain.repository.OrganizationalEmployeeQueryRepository; import com.hrcoresystem.hrcore_api.common.exception.ResourceNotFoundException; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import java.time.LocalDate; import java.util.UUID;
@Service public class ListPositionEmployeesUseCase { private final OrganizationalEmployeeQueryRepository repo; private final TenantTimezoneService timezone; private final PositionRepository positions; public ListPositionEmployeesUseCase(OrganizationalEmployeeQueryRepository r,TenantTimezoneService t,PositionRepository p){repo=r;timezone=t;positions=p;} public Page<OrganizationalEmployeeSummaryResponse> execute(UUID id,LocalDate date,Pageable p){if(positions.findById(id).isEmpty()) throw new ResourceNotFoundException("Cargo no encontrado"); return repo.findByPosition(id,date==null?timezone.today():date,p);} }
